xy_err_cm = xy_err_m * 100;

%% ── Pre-computed constants ───────────────────────────────────────────────────
T_DIST      = 5.0;
true_hold_x = -0.1403;
true_hold_y = -0.3166;
pre_rmse_cm = 1.8210;
max_drift_cm= 11.6800;
t_max_drift = 6.0250;
tau_rec     = 0.5833;
return_time = 1.7500;
t_recovered = 6.7500;
threshold_m = 0.0500;

dx = x_true - true_hold_x;
dy = y_true - true_hold_y;

%% ── Decay envelopes ─────────────────────────────────────────────────────────
mask_pp  = T >= t_max_drift;
ref_env  = NaN(size(T));  lit_fast = NaN(size(T));  lit_slow = NaN(size(T));
ref_env(mask_pp)  = max_drift_cm * exp(-(T(mask_pp) - t_max_drift) / tau_rec);
lit_fast(mask_pp) = max_drift_cm * exp(-(T(mask_pp) - t_max_drift) / 1.0);
lit_slow(mask_pp) = max_drift_cm * exp(-(T(mask_pp) - t_max_drift) / 3.0);

%% ── Trajectory phases ────────────────────────────────────────────────────────
pre_mask  = T < T_DIST;
dur_mask  = T >= T_DIST & T <= t_recovered;
post_mask = T >= t_recovered;

%% ── Colours ──────────────────────────────────────────────────────────────────
cPre  = [0.25 0.72 0.38];  cDur  = [1.00 0.60 0.10];
cPost = [0.20 0.55 0.85];  cSP   = [0.85 0.18 0.18];
cFill = [0.27 0.51 0.71];
theta_c = linspace(0, 2*pi, 200);

%% ── Figure 1 — XY Trajectory ─────────────────────────────────────────────────
fig1 = figure('Name','B2 — XY Trajectory','Position',[60 60 880 880]);
ax_xy = axes(fig1);  hold on;
if any(pre_mask)
    plot(ax_xy, dx(pre_mask), dy(pre_mask), '-', 'Color',cPre, 'LineWidth',2.0, ...
         'DisplayName','Pre-disturbance');
end
if any(dur_mask)
    plot(ax_xy, dx(dur_mask), dy(dur_mask), '-', 'Color',cDur, 'LineWidth',2.0, ...
         'DisplayName','Disturbance \rightarrow recovery');
end
if any(post_mask)
    plot(ax_xy, dx(post_mask), dy(post_mask), '-', 'Color',[cPost 0.6], 'LineWidth',1.5, ...
         'DisplayName','Post-recovery');
end
scatter(ax_xy, 0, 0, 120, cSP, 'filled', 'DisplayName','Setpoint');
scatter(ax_xy, dx(end), dy(end), 120, cPost, 'd', 'filled', ...
        'DisplayName', sprintf('Final pos (%.1f, %.1f) cm', dx(end)*100, dy(end)*100));
plot(ax_xy, 0.05*cos(theta_c), 0.05*sin(theta_c), '--', 'Color',cSP, 'LineWidth',1.5, ...
     'DisplayName','5 cm acceptance boundary [Ref 2, 4]');
axis(ax_xy,'equal');
set(ax_xy,'Box','off','XGrid','on','YGrid','on','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_xy,'\DeltaX from setpoint  (m)','FontSize',25);
ylabel(ax_xy,'\DeltaY from setpoint  (m)','FontSize',25);
title(ax_xy,'XY Trajectory (relative to setpoint)','FontSize',25);
leg1 = legend(ax_xy,'FontSize',16,'NumColumns',2);  leg1.Location='southoutside';
hold off;

%% ── Figure 2 — Altitude ──────────────────────────────────────────────────────
fig2 = figure('Name','B2 — Altitude','Position',[80 60 1120 800]);
ax_alt = axes(fig2);  hold on;
plot(ax_alt, T, z_true, '-', 'Color',[.55 .15 .75], 'LineWidth',2.0, 'DisplayName','Altitude  (m)');
xline(ax_alt, T_DIST, '--', 'Color','red', 'LineWidth',1.5, 'DisplayName','Disturbance');
patch(ax_alt, [T(1) T(end) T(end) T(1)], [0.98 0.98 1.02 1.02], ...
      [.25 .72 .38], 'FaceAlpha',.15, 'EdgeColor','none', 'DisplayName','\pm2 cm acceptance band [Ref 2]');
yline(ax_alt, 1.0, ':', 'Color',[.25 .72 .38], 'LineWidth',0.8, 'HandleVisibility','off');
set(ax_alt,'XLim',[0 T(end)],'Box','off','YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_alt,'Time  (s)','FontSize',25);
ylabel(ax_alt,'Altitude  (m)','FontSize',25);
title(ax_alt,{'Altitude during Disturbance'; 'Lit. SS altitude error <2 cm [Ref 2]'},'FontSize',25);
leg2 = legend(ax_alt,'FontSize',20,'NumColumns',3);  leg2.Location='southoutside';
hold off;

%% ── Figure 3 — XY Error ──────────────────────────────────────────────────────
fig3 = figure('Name','B2 — XY Error','Position',[100 60 1000 1500]);
ax_err = axes(fig3);  hold on;
plot(ax_err, T, xy_err_cm, '-', 'Color',[1.00 0.60 0.10], 'LineWidth',2.0, ...
     'DisplayName','XY distance from setpoint  (cm)');
plot(ax_err, T, ref_env, ':', 'Color',[.5 .5 .5], 'LineWidth',1.5, ...
     'DisplayName', sprintf('Fitted decay envelope (\\tau=%.2f s)', tau_rec));
plot(ax_err, T, lit_fast, '--', 'Color',cFill, 'LineWidth',1.5, ...
     'DisplayName','Lit. fast recovery (\tau=1 s) [Ref 3]');
plot(ax_err, T, lit_slow, '--', 'Color',[0 0 .5], 'LineWidth',1.5, ...
     'DisplayName','Lit. slow recovery (\tau=3 s) [Ref 3]');
xline(ax_err, T_DIST, '--', 'Color','red', 'LineWidth',1.5, 'DisplayName','Disturbance');
yline(ax_err, pre_rmse_cm, ':', 'Color',[.25 .72 .38], 'LineWidth',1.2, ...
      'DisplayName', sprintf('Pre-disturbance RMSE = %.2f cm', pre_rmse_cm));
yline(ax_err, max_drift_cm, ':', 'Color','red', 'LineWidth',1.2, ...
      'DisplayName', sprintf('Max drift = %.2f cm', max_drift_cm));
xline(ax_err, T_DIST+return_time, ':', 'Color','blue', 'LineWidth',1.2, ...
      'DisplayName', sprintf('Recovered at +%.1f s', return_time));
set(ax_err,'XLim',[0 T(end)],'Box','off','YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_err,'Time  (s)','FontSize',25);
ylabel(ax_err,'XY error  (cm)','FontSize',25);
title(ax_err, {'EXP-B2: Position Hold Disturbance Rejection  (F_x=0.05 N for 0.2 s)'; ...
               'Literature: recovery 1-3 s, SS-RMSE <5 cm [Ref 2, 3]'}, 'FontSize',25);
leg3 = legend(ax_err,'FontSize',25,'NumColumns',1);  leg3.Location='southoutside';
hold off;
